"""Concise continuation report; original measurements and zero-call diagnostics stay distinct."""
import json,hashlib
from pathlib import Path
from collections import Counter
OLD=Path('evaluation/briefing-quality/private/reliability-v1');ROOT=Path('evaluation/briefing-quality/private/reliability-v2');OUT=Path('evaluation/briefing-quality/reports/reliability-v2')
def load(p):return json.loads(Path(p).read_text(encoding='utf-8'))
def ratio(n,d):return n/d if d else None
def summarize():
 audited_root=ROOT/'r2' if (ROOT/'r2/revalidation.private.json').exists() else ROOT
 prior=load('evaluation/briefing-quality/reports/reliability-v1/FINAL_RESULTS.json');revalidation=load(audited_root/'revalidation.private.json');checks=load(ROOT/'checks/latest.json');current=load(ROOT/'current-engine-manifest.private.json');category_metrics={};failures=[]
 for dataset,root in [('synthetic',OLD),('real-source',OLD/'real-challenges')]:
  audit=load(audited_root/(dataset+'-reference-audit.json'));references={r['id']:r for r in audit['rows']}
  for model in ['openai--gpt-4.1','anthropic--claude-sonnet-4.5']:
   rows=[load(p) for p in (root/'controls-run'/model).glob('*/result.private.json')];complete=[r for r in rows if r['status']=='completed'];key=dataset+'/'+model;strata={}
   for language in ['all','en','ar','fr']:
    subset=[r for r in complete if language=='all' or r['language']==language];categories={}
    for category in ['factual','citation','coverage','relevance','repetition','temporal','language']:
     c={'TP':0,'FP':0,'TN':0,'FN':0};masked=0
     for r in subset:
      truth=references[r['id']]['strictExpected'].get(category)
      if truth is None:masked+=1;continue
      prediction=bool(r['predicted'][category]);c[('T' if prediction==bool(truth) else 'F')+('P' if prediction else 'N')]+=1
     categories[category]={**c,'precision':ratio(c['TP'],c['TP']+c['FP']),'recall':ratio(c['TP'],c['TP']+c['FN']),'f1':ratio(2*c['TP'],2*c['TP']+c['FP']+c['FN']),'masked':masked}
    strata[language]={'completed':len(subset),'categories':categories}
   category_metrics[key]={'planned':len(references),'recordedResults':len(rows),'completed':len(complete),'failedResults':sum(r['status']=='failed' for r in rows),'strata':strata,'scoreOrigin':'Saved v1 model judgments with v2 reference mask; no new judge inference'}
   failures.extend({'dataset':dataset,'model':model,'id':r['id'],'error':r.get('error'),'phase':r.get('phase')} for r in rows if r['status']=='failed')
 result={'continuationFrom':'17edc3ec','policy':'independent-language-structured-consistency-v2','freshModelCalls':0,'freshInferenceCostUsd':0,'originalConfirmedResearchCostUsd':prior['financials']['settledUsd'],'originalConservativeHoldsUsd':prior['financials']['unresolvedReservationUsd'],'benchmarkAudits':{d:{k:v for k,v in load(ROOT/(d+'-reference-audit.json')).items() if k!='rows'} for d in ['synthetic','real-source']},'originalFailureAudit':failures,'auditedSavedJudgmentMetrics':category_metrics,'independentLanguageChecks':revalidation['detectorStats'],'correctionsPrepared':sum(bool(r.get('correction')) for r in revalidation['rows']),'newCorrectionCallsExecuted':0,'currentEngineInputs':{'ready':sum(c['status']=='ready' for c in current['cases']),'executed':0,'optionsValidatedAgainst':'apps/worker/src/v1-intelligence/v3-window.ts:180'},'heldOut':{'suitableCertifiedWindows':0,'reason':'All available nonempty post-freeze snapshots had partial/unknown source completeness; event independence not certified. Exposed windows remain development.'},'localChecks':checks,'deployment':'none','providerBlocker':'Account balance approximately -$0.03; key allowance is not account funding. User selected finishing available work and pushing.','sourceHashes':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in Path('evaluation/briefing-quality/validation').glob('*') if p.is_file()}}
 lines=['# Briefing evaluation research: continuation findings','','**Finding:** the existing evaluator is useful triage, with demonstrated language and structured-output weaknesses. The available evidence does not establish that the current Distilled.news engine outperforms all simpler baselines. This continuation adds safeguards and revalidates saved evidence; it does not claim new paid-model measurements.','','## What was actually done','','- Audited all 54 original benchmark source/reference pairs: 42 constructed cases and 12 retained-source mutations/controls. Source IDs, exact source text and hashes matched. No original reference or paid artifact was overwritten.','- Flagged semantic limits: wrong dates overlap factual/temporal categories; partial district coverage depends on inventory granularity; “correct control” does not independently certify that every judge-selected important development is covered. The v2 audit masks control coverage instead of treating subjective omissions as known false positives. References remain AI-curated, not human gold.','- Added a pinned independent TinyLD 1.3.4 narration checker. It assesses requested output language, allows multilingual quotations, and abstains on names, short ambiguous text and mixed narration. Its scores are not calibrated probabilities.','- Added one bounded, separately accounted correction path for internally inconsistent judge output. It retains the original response, source inventory and paid record. Invalid foreign evidence is not repaired; a still-inconsistent response remains failed. This path passed regression/provider-double tests but has not been validated in new live model calls.','- Retrieved and verified six original frozen engine inputs, including real publisher metadata and source-accounting, citation and novelty policies. The new replay adapter mirrors the actual `v3-window.ts` invocation. Earlier core-default replay scores are preserved and cannot be advertised as current-engine performance.','','## Independent language revalidation (zero inference calls)','','| Source set | Eligible controls/swaps | Classifiable | Abstained | TP / FP / TN / FN among classifiable |','| --- | ---: | ---: | ---: | --- |']
 for dataset,m in revalidation['detectorStats'].items():lines.append(f"| {dataset} | {m['eligible']} | {m['classifiable']} | {m['abstentions']} | {m['TP']} / {m['FP']} / {m['TN']} / {m['FN']} |")
 lines+=['','The checker flags two of the three recorded GPT wrong-language misses and abstains on the third. The combined candidate result marks that third case uncertain, not correct. This is development revalidation, not a fresh GPT/Claude rerun or held-out sensitivity estimate. No high score is inferred from excluding abstentions.','','## Recorded model results and failures','','The prior blind run attempted 42 constructed cases and 12 real-source cases per judge. GPT completed 37/42 and 12/12; Claude completed 37/42 and 11/12. Completed-only constructed any-fault precision/recall/F1 were GPT **100% / 82.4% / 90.3%**, Claude **94.1% / 100% / 97.0%**. Real-source completed-only results were GPT **100% / 100% / 100%**, Claude **85.7% / 100% / 92.3%**. Different failed subsets, dependent translations and artificial prevalence prevent treating these as a ranking or production accuracy.','',f"This continuation prepared **{result['correctionsPrepared']}** consistency-correction requests from saved failed replies and sent **zero**. Original failures, full seven-category TP/FP/TN/FN, precision/recall/F1, language strata and masked denominators are in `RESEARCH_RESULTS.json`. Original provider rejections, unknown operations and schema failures remain failures; raw concern detection is not promoted to a successful review.",'','## Which system performs better?','','- **Wrong-language injections:** Claude detected all three in the original completed sample; GPT missed all three. Claude also had false positives on legitimate controls. No overall family superiority follows.','- **Simple source-relative quantity/modality faults:** GPT detected all six real-source mutations in the small completed sample. Two events translated three ways are not six independent events.','- **Earlier core-default baseline trials:** among completed historical assessments, all-headlines had 100% judged development recall versus 75% for single-LLM, at 616 versus 141 output words. On two prospective matched V3/single-LLM assessments, observed claim-support and recall differences were zero. These results are exploratory, small, incompletely assessed and **not** a completed current-engine comparison.','- **Actual published briefings:** six existing deployed reports were previously snapshot-hash verified; all five extracted claims were judged supported and correctly cited, while potential omissions appeared in some windows. Partial evidence and a fallible judge prevent certification of factual completeness.','- **Current-engine superiority:** inconclusive. Original frozen options are now available, but the fully matched current-engine generation/judging campaign is unperformed because account credit is exhausted.','','## Costs, validation and blockers','',f"New inference calls/cost this continuation: **0 / $0**. Prior confirmed study cost: **${result['originalConfirmedResearchCostUsd']:.6f}**. Prior conservative unresolved holds: **${result['originalConservativeHoldsUsd']:.6f}**; those are not settled charges. No old ledger was rewritten.",'','The provider account was approximately **-$0.03**, despite about $16.37 of unused key allowance. The user selected finishing available work and pushing. Fresh full GPT/Claude reruns, paid consistency corrections and complete current-engine paired scoring remain blocked by account funding. No exposed development window has been relabeled untouched; no suitable certified event-independent held-out set was established.','',f"Local check runner status: **{checks['status']}**. It covers evaluation Python tests, evaluator/replay tests, existing engine tests, exporter tests and three TypeScript checks. Research Python tests are run separately. GitHub workflow results for the pushed commit are reported separately, not assumed from local tests.",'','All candidate behavior stays offline. No deployment, production resource change, dashboard change, publication modification, or merge to main was made. Before any monitoring deployment, obtain separate approval and validate the new policy with fresh independent data and complete failure-aware measurement.','']
 lines+=['## Independent review and CI follow-up','','Independent review found and verified fixes for Arabic name-list false language classification and silently cleared adverse assessments. Corrections now retain original/replacement raw replies and require explicit reconsideration explanations per claim, item or development. Explanation text and claim meaning still need semantic validation; a trace is not factual proof. The first diagnostic remains preserved; post-review results are in `OFFLINE_REVALIDATION_R2.json`.','', 'GitHub’s initial dedicated Briefing evaluation workflow passed. The wider Project checks exposed six pre-existing model test doubles missing required token-count fields. Their test-only responses were corrected without changing assertions or production code. Corrective-commit CI results are reported separately. One local pre-existing Miniflare retention test exceeded its five-second host deadline; its failed run log is retained and unchanged checks were rerun.','']
 OUT.mkdir(parents=True,exist_ok=True);(OUT/'RESEARCH_RESULTS.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8');(OUT/'RESEARCH_REPORT.md').write_text('\n'.join(lines),encoding='utf-8');print(json.dumps({'report':str(OUT/'RESEARCH_REPORT.md'),'freshModelCalls':0,'checks':checks['status'],'correctionsPrepared':result['correctionsPrepared']}))
